const $=s=>document.querySelector(s),registerView=$('#register-view'),loginView=$('#login-view'),statusView=$('#status-view');
const banks=[['001','Banco do Brasil'],['003','Banco da Amazônia'],['004','Banco do Nordeste'],['021','Banestes'],['033','Santander Brasil'],['041','Banrisul'],['047','Banco do Estado de Sergipe'],['070','BRB'],['077','Banco Inter'],['104','Caixa Econômica Federal'],['121','Agibank'],['197','Stone Instituição de Pagamento'],['208','BTG Pactual'],['212','Banco Original'],['237','Bradesco'],['260','Nu Pagamentos (Nubank)'],['290','PagBank'],['318','Banco BMG'],['323','Mercado Pago'],['336','C6 Bank'],['341','Itaú Unibanco'],['380','PicPay'],['389','Banco Mercantil do Brasil'],['422','Banco Safra'],['655','Banco Votorantim'],['748','Sicredi'],['756','Sicoob']];
$('#banks').innerHTML=banks.map(([code,name])=>`<option value="${code} - ${name}"></option>`).join('');
const api=async(url,options={})=>{const response=await fetch(url,{cache:'no-store',...options}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Não foi possível concluir a operação.');return data};
const show=view=>{registerView.hidden=view!=='register';loginView.hidden=view!=='login';statusView.hidden=view!=='status';scrollTo({top:0,behavior:'smooth'})};
$('#show-register').onclick=()=>show('register');$('#show-login').onclick=()=>show('login');
const onlyDigits=value=>String(value||'').replace(/\D/g,'');
const mask=(input,type)=>{let v=onlyDigits(input.value);if(type==='cpf')v=v.slice(0,11).replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d{1,2})$/,'$1-$2');if(type==='cnpj')v=v.slice(0,14).replace(/(\d{2})(\d)/,'$1.$2').replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d)/,'$1/$2').replace(/(\d{4})(\d{1,2})$/,'$1-$2');if(type==='cep')v=v.slice(0,8).replace(/(\d{5})(\d)/,'$1-$2');input.value=v};
const form=$('#register-form');form.elements.cpf.addEventListener('input',e=>mask(e.target,'cpf'));form.elements.cnpj.addEventListener('input',e=>mask(e.target,'cnpj'));form.elements.cep.addEventListener('input',e=>mask(e.target,'cep'));
form.elements.possuiCnpj.addEventListener('change',e=>{$('#cnpj-field').hidden=!e.target.checked;form.elements.cnpj.required=e.target.checked;if(!e.target.checked)form.elements.cnpj.value=''});
form.elements.cep.addEventListener('blur',async()=>{const cep=onlyDigits(form.elements.cep.value),message=$('#cep-message');if(cep.length!==8)return;message.textContent='Consultando CEP…';try{const response=await fetch(`https://viacep.com.br/ws/${cep}/json/`),data=await response.json();if(data.erro)throw new Error();const parts=String(data.logradouro||'').split(' '),known=['Rua','Avenida','Travessa','Estrada','Rodovia','Alameda','Praça','Largo','Viela'];form.elements.tipoLogradouro.value=known.includes(parts[0])?parts.shift():form.elements.tipoLogradouro.value;form.elements.logradouro.value=parts.length?parts.join(' '):data.logradouro||'';form.elements.bairro.value=data.bairro||'';form.elements.cidade.value=data.localidade||'';form.elements.uf.value=data.uf||'';message.textContent='Endereço localizado.'}catch{message.textContent='CEP não localizado. Preencha o endereço manualmente.'}});
$('#bank-search').addEventListener('change',e=>{const match=banks.find(([code,name])=>`${code} - ${name}`===e.target.value);form.elements.bancoCodigo.value=match?.[0]||'';form.elements.bancoNome.value=match?.[1]||''});
form.addEventListener('submit',async e=>{e.preventDefault();const message=$('#register-message'),button=e.currentTarget.querySelector('button[type=submit]');message.className='form-message';message.textContent='';if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));values.possuiCnpj=form.elements.possuiCnpj.checked;values.aceiteLgpd=form.elements.aceiteLgpd.checked;values.aceiteAutonomo=form.elements.aceiteAutonomo.checked;values.aceiteAntecedentes=form.elements.aceiteAntecedentes.checked;values.bancoCodigo=form.elements.bancoCodigo.value;values.bancoNome=form.elements.bancoNome.value;if(!values.bancoCodigo){message.textContent='Selecione um banco válido na lista.';return}button.disabled=true;try{await api('/api/montadores/cadastro',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});form.reset();message.className='form-message success';message.textContent='Cadastro recebido. Abrindo seu acompanhamento…';await loadStatus();show('status')}catch(error){message.textContent=error.message}finally{button.disabled=false}});
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const message=$('#login-message'),button=e.currentTarget.querySelector('button');button.disabled=true;message.textContent='';try{await api('/api/montadores/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});e.currentTarget.reset();await loadStatus();show('status')}catch(error){message.textContent=error.message}finally{button.disabled=false}});
const labels={CADASTRO_RECEBIDO:'Cadastro recebido',PENDENTE_DOCUMENTO:'Pendente de certidão',EM_ANALISE:'Em análise',APROVADO:'Aprovado',REJEITADO:'Não aprovado',SUSPENSO:'Suspenso',PENDENTE:'Pendente',REJEITADO:'Rejeitado'};
const formatDate=value=>value?new Date(value).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'—';
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
async function loadStatus(){const data=await api('/api/montadores/status');$('#status-name').textContent=data.montador.nomeCompleto;const approved=data.montador.statusCadastro==='APROVADO';$('#status-card').innerHTML=`<div class="status-card"><article><span>Status do cadastro</span><strong class="${approved?'approved':'pending'}">${labels[data.montador.statusCadastro]||data.montador.statusCadastro}</strong></article><article><span>Certidão</span><strong>${labels[data.montador.certidaoStatus]||data.montador.certidaoStatus}</strong></article><article><span>Última atualização</span><strong>${formatDate(data.montador.atualizadoEm)}</strong></article></div>${data.pendencias.certidao?'<div class="notice"><strong>Pendência obrigatória:</strong> anexe uma certidão válida para que o cadastro possa ser analisado e aprovado.<a class="notice-action" href="#certificate-form">Anexar certidão agora</a></div>':''}`;$('#documents-list').innerHTML=data.documentos.length?data.documentos.map(doc=>`<div class="document"><div><strong>${doc.tipo==='CERTIDAO_ANTECEDENTES'?'Certidão de antecedentes':'NFS-e'}</strong><small>${escapeHtml(doc.nome_arquivo)} · ${formatDate(doc.criado_em)}</small></div><span>${labels[doc.status_revisao]||doc.status_revisao}</span></div>`).join(''):'<p>Nenhum documento enviado.</p>'}
const fileBase64=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});
async function upload(formElement,tipo){const message=formElement.querySelector('.form-message'),button=formElement.querySelector('button'),file=formElement.elements.file.files[0];if(!file)return;button.disabled=true;message.textContent='Enviando…';try{const body={tipo,fileName:file.name,mimeType:file.type,data:await fileBase64(file)};if(tipo==='NOTA_FISCAL_SERVICO'){body.valorTotal=formElement.elements.valorTotal.value;body.referenciaPagamento=formElement.elements.referenciaPagamento.value}await api('/api/montadores/documento',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});formElement.reset();message.className='form-message success';message.textContent='Documento enviado para revisão.';await loadStatus()}catch(error){message.className='form-message';message.textContent=error.message}finally{button.disabled=false}}
$('#certificate-form').addEventListener('submit',e=>{e.preventDefault();upload(e.currentTarget,'CERTIDAO_ANTECEDENTES')});$('#invoice-form').addEventListener('submit',e=>{e.preventDefault();upload(e.currentTarget,'NOTA_FISCAL_SERVICO')});
$('#logout').addEventListener('click',async()=>{await fetch('/api/montadores/logout',{method:'POST'});show('login')});
api('/api/montadores/status').then(()=>loadStatus()).then(()=>show('status')).catch(()=>{});
